import Foundation

/// Positive signature of the hierarchy identifiers generated by Qt's Cocoa
/// bridge, used as one prerequisite of Qt list receiver/stacking proofs.
/// This signature establishes neither UI ownership nor action equivalence.
enum NativeQtAccessibilityIdentifier {
    private static let widgetComponents: Set<String> = [
        "QWidget", "QDialog", "QMainWindow", "QScrollArea", "QListWidget", "QListView", "QTreeWidget", "QTreeView",
        "QTableWidget", "QTableView", "QCheckBox", "QRadioButton", "QPushButton", "QComboBox", "QComboBoxListView",
        "qt_scrollarea_viewport"
    ]

    static func isWidgetPath(_ identifier: String?) -> Bool {
        guard let identifier else { return false }
        let components = identifier.split(separator: ".", omittingEmptySubsequences: false)
        guard components.count >= 3, components.first == "QApplication", !components.contains(where: \.isEmpty) else {
            return false
        }
        return components.dropFirst().contains { widgetComponents.contains(String($0)) }
    }
}
